class Solution:
 def numMagicSquaresInside(self,grid):
  m,n=len(grid),len(grid[0]);ans=0
  for r in range(m-2):
   for c in range(n-2):
    vals=[grid[i][j] for i in range(r,r+3) for j in range(c,c+3)]
    if len(set(vals))!=9 or set(vals)!=set(range(1,10)):continue
    if grid[r+1][c+1]!=5:continue
    lines=[sum(grid[r+i][c+j] for j in range(3)) for i in range(3)]+[sum(grid[r+i][c+j] for i in range(3)) for j in range(3)]+[sum(grid[r+i][c+i] for i in range(3)),sum(grid[r+i][c+2-i] for i in range(3))]
    if all(x==15 for x in lines):ans+=1
  return ans

class Solution:
 def backspaceCompare(self,s,t):
  def build(x):
   out=[]
   for c in x:
    if c=='#':
     if out:out.pop()
    else:out.append(c)
   return ''.join(out)
  return build(s)==build(t)

class Solution:
 def maxDistToClosest(self,seats):
  n=len(seats);prev=-1;best=0
  for i,x in enumerate(seats):
   if x:
    best=max(best,i if prev==-1 else (i-prev)//2);prev=i
  return max(best,n-1-prev)

class Solution:
 def peakIndexInMountainArray(self,arr):
  lo=0;hi=len(arr)-1
  while lo<hi:
   mid=(lo+hi)//2
   if arr[mid]<arr[mid+1]:lo=mid+1
   else:hi=mid
  return lo

class Solution:
 def buddyStrings(self,s,goal):
  if len(s)!=len(goal):return False
  if s==goal:return len(set(s))<len(s)
  diff=[i for i,(a,b) in enumerate(zip(s,goal)) if a!=b]
  return len(diff)==2 and s[diff[0]]==goal[diff[1]] and s[diff[1]]==goal[diff[0]]

class Solution:
 def lemonadeChange(self,bills):
  five=ten=0
  for b in bills:
   if b==5:five+=1
   elif b==10:
    if five==0:return False
    five-=1;ten+=1
   else:
    if ten and five:ten-=1;five-=1
    elif five>=3:five-=3
    else:return False
  return True

class Solution:
 def binaryGap(self,n):
  last=-1;best=0;pos=0
  while n:
   if n&1:
    if last!=-1:best=max(best,pos-last)
    last=pos
   pos+=1;n>>=1
  return best

class Solution:
 def leafSimilar(self,root1,root2):
  def leaves(root):
   out=[];stack=[root] if root else []
   while stack:
    n=stack.pop()
    if n.left is None and n.right is None:out.append(n.val)
    else:
     if n.right:stack.append(n.right)
     if n.left:stack.append(n.left)
   return out
  return leaves(root1)==leaves(root2)
